from pathlib import Path
import json,subprocess,sys,os,hashlib,datetime,threading,time,re
root=Path.cwd();sys.path.insert(0,str(root/'benchmarks/iteration/unity/current'))
import s8_project as project
import recovery
out=root/'target/perf-win-2026-11-09/clr-unity';out.mkdir(exist_ok=False)
proof=root/'target/ecs-clr-scheduling-20261109T082021Z';exe=proof/'candidate/ecs_kernel_bench'
clr_env=os.environ|{'ARA_DOTNET_PREBUILT':'1','DOTNET_ROOT':str(root/'target/toolchains/dotnet'),'DOTNET_CLI_HOME':str(root/'target/toolchains/cli-home'),'DOTNET_TieredCompilation':'0','PATH':str(root/'target/toolchains/dotnet')+':'+os.environ['PATH']}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def context(owned):
 rows=[]
 for line in subprocess.check_output(['ps','-axo','pid=,ppid='],text=True).splitlines():
  a=line.split()
  if len(a)==2:rows.append(tuple(map(int,a)))
 while True:
  next_={pid for pid,parent in rows if parent in owned}
  if next_<=owned:break
  owned.update(next_)
 c=project.features.resources(strict=False)
 c['owned_tools']=[r for r in c['busy_tools'] if int(r['pid']) in owned]
 c['busy_tools']=[r for r in c['busy_tools'] if int(r['pid']) not in owned]
 c['utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 return c
report={'scope':'Actual generated Ara C# Span/Vector128 gameplay vs Unity Editor Burst, same12f32 contract, two reversed fresh rounds','candidate_sha256':sha(exe),'paired_build_proof':str(proof),'tiered_compilation':'0','results':[]}
def clr_case(name,workload,runners,warmup):
 owned=set();before=context(owned)
 if before['busy_tools']:raise RuntimeError(before)
 dump=out/(name+'.bin');argv=['/usr/bin/nice','-n','10',str(exe),'--workload',workload,'--mode','simd','--rows','1000000','--threads',str(runners),'--warmup',str(warmup),'--samples','300','--dump',str(dump)]
 with (out/(name+'.stdout')).open('w') as stdout, (out/(name+'.stderr')).open('w') as stderr:
  child=subprocess.Popen(argv,env=clr_env,stdout=stdout,stderr=stderr);owned.add(child.pid);observed=[];runtime=None;runtime_probe_before_setup=False
  start=time.monotonic()
  while child.poll() is None:
   if time.monotonic()-start>600:child.terminate();child.wait(timeout=10);raise RuntimeError('CLR timeout')
   try: child.wait(timeout=1)
   except subprocess.TimeoutExpired:pass
   if child.poll() is None:
    observed.append(context(owned))
    if runtime is None and 'setup_complete' not in (out/(name+'.stderr')).read_text():
     lsof=subprocess.run(['/usr/sbin/lsof','-a','-p',str(child.pid),'-Fn'],capture_output=True,text=True,timeout=5)
     hit=re.search(r'(/[^\n]+/shared/Microsoft.NETCore.App/([^/]+)/libcoreclr.dylib)',lsof.stdout)
     if hit:runtime={'image':hit[1],'version':hit[2]};runtime_probe_before_setup='setup_complete' not in (out/(name+'.stderr')).read_text()
  status=child.wait()
 after=context(owned);raw=(out/(name+'.stdout')).read_text();result=next((json.loads(s) for s in reversed(raw.splitlines()) if s.startswith('{')),None)
 if status or result is None:raise RuntimeError(f'CLR failed{name}, status{status}')
 accepted=not any(c['busy_tools'] for c in [before,*observed,after]) and len({c['power'].splitlines()[0] for c in [before,*observed,after]})==1
 entry={'command':argv,'before':before,'after':after,'observations':observed,'owned_process_ids':sorted(owned),'runtime':runtime,'runtime_probe_before_setup':runtime_probe_before_setup,'exit_code':status,'timings_accepted':accepted,'result':result,'dump':str(dump),'dump_sha256':sha(dump),'stdout_sha256':sha(out/(name+'.stdout')),'stderr_sha256':sha(out/(name+'.stderr'))}
 if not accepted:raise RuntimeError('CLR resources/power invalid: '+name)
 return entry
for round_ in range(2):
 cases=[(w,t) for w in ['w1','w3'] for t in [1,15]]
 for workload,runners in (cases if round_==0 else reversed(cases)):
  warmup=120 if workload=='w1' else 3000;name=f'r{round_}-{workload}-t{runners}';run='clr-matched-'+name
  common=['--workload',workload,'--count','1000000','--runners',str(runners),'--warmup',str(warmup),'--frames','300','--batch','8192' if workload=='w3' else '4096','--run',run]
  engines={}
  for engine in (['clr','unity'] if round_==0 else ['unity','clr']):
   if engine=='clr':engines['clr']=clr_case(name,workload,runners,warmup)
   else:
    argv=['/usr/bin/nice','-n','10',sys.executable,str(root/'benchmarks/iteration/unity/current/run.py'),'run-unity',*common]
    p=subprocess.run(argv,capture_output=True,text=True,timeout=900);(out/(name+'.unity.stdout')).write_text(p.stdout);(out/(name+'.unity.stderr')).write_text(p.stderr)
    if p.returncode:raise RuntimeError(f'Unity failed {name}; preserve guards, no retry: '+p.stderr)
    stem=project.PROJECT/'results'/run/f'{workload}_1000000_r{runners}_unity';result=Path(str(stem)+'.json');dump=Path(str(stem)+'.bin');launch=Path(str(stem)+'.launch.json')
    engines['unity']={'command':argv,'result':json.loads(result.read_text()),'launch':json.loads(launch.read_text()),'result_path':str(result),'result_sha256':sha(result),'launch_path':str(launch),'launch_sha256':sha(launch),'dump':str(dump),'dump_sha256':sha(dump)}
   print(name,engine,engines[engine]['result']['p50_ms'],flush=True)
  c,u=engines['clr'],engines['unity'];assert Path(c['dump']).read_bytes()==Path(u['dump']).read_bytes()
  assert c['result']['validation']['every_field_bitwise_valid'] and c['result']['validation']['exact_ids_and_component_presence']
  assert u['launch']['timings_accepted'] and c['timings_accepted']
  assert c['before']['power'].splitlines()[0]==u['launch']['before']['power'].splitlines()[0]
  row={'name':name,'workload':workload,'runners':runners,'same_full_state_bytes':True,'state_bytes':1000000*48,'engines':engines,'p50_fraction_lower':1-c['result']['p50_ms']/u['result']['p50_ms'],'p95_fraction_change':c['result']['p95_ms']/u['result']['p95_ms']-1}
  row['target_met']=row['p50_fraction_lower']>=.20 and row['p95_fraction_change']<=.05
  report['results'].append(row);(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(name,'COMPLETE target',row['target_met'],flush=True)
report['complete']=True;recovery.ensure_clear(project.PROJECT);(out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
